mapper.select:
SELECT touches.deal_id AS deal_id, MAX(touches.touched_at) AS touched_at
FROM (
  SELECT a.deal_id, a.timestamp AS touched_at
  FROM activity a
  WHERE a.workspace_id = #{workspaceId}
    AND a.deal_id IN
    #{id}
    AND a.timestamp <= #{now}
  UNION ALL
  SELECT n.deal_id, n.created_at AS touched_at
  FROM note n
  WHERE n.workspace_id = #{workspaceId}
    AND n.visibility = 'workspace'
    AND n.deal_id IN
    #{id}
    AND n.created_at <= #{now}
  UNION ALL
  SELECT t.deal_id, t.created_at AS touched_at
  FROM task t
  WHERE t.workspace_id = #{workspaceId}
    AND t.deal_id IN
    #{id}
    AND t.created_at <= #{now}
) touches
GROUP BY touches.deal_id

SELECT FROM deal d
LEFT JOIN company c ON c.id = d.company_id AND LEFT JOIN pipeline p ON p.id = d.pipeline_id AND LEFT JOIN stage s ON s.id = d.stage_id AND s.pipeline_id = d.pipeline_id AND
LIMIT #{limit} OFFSET #{offset}

SELECT d.id FROM deal d
LEFT JOIN company c ON c.id = d.company_id AND LEFT JOIN pipeline p ON p.id = d.pipeline_id AND LEFT JOIN stage s ON s.id = d.stage_id AND s.pipeline_id = d.pipeline_id AND
ORDER BY d.id LIMIT #{limit}

SELECT MIN(d.closed_at) AS earliest, MAX(d.closed_at) AS latest FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.closed_at IS NOT NULL AND (d.won = FALSE OR d.expected_close_date IS NULL) AND d.actual_value != 0

SELECT boundary.local_year AS year, boundary.local_month AS month, ( SELECT SUM(d.actual_value) FROM deal d FORCE INDEX FOR JOIN (idx_deal_workspace_closed_at) WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.closed_at >= boundary.start_utc AND d.closed_at < boundary.end_utc AND (d.won = FALSE OR d.expected_close_date IS NULL) AND d.actual_value != 0 ) AS total FROM (
SELECT #{boundary.year} AS local_year, #{boundary.month} AS local_month, #{boundary.startUtc} AS start_utc, #{boundary.endUtc} AS end_utc
) boundary HAVING total IS NOT NULL ORDER BY boundary.local_year, boundary.local_month

SELECT YEAR(d.expected_close_date) AS year, MONTH(d.expected_close_date) AS month, COALESCE(SUM(d.actual_value), 0) AS total FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.closed_at IS NOT NULL AND d.won = TRUE AND d.expected_close_date IS NOT NULL GROUP BY YEAR(d.expected_close_date), MONTH(d.expected_close_date)

SELECT YEAR(d.expected_close_date) AS year, MONTH(d.expected_close_date) AS month, COALESCE(SUM(d.value), 0) AS total FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.expected_close_date IS NOT NULL GROUP BY YEAR(d.expected_close_date), MONTH(d.expected_close_date)

SELECT d.stage_id AS stage_id, d.pipeline_id AS pipeline_id, COUNT(CASE WHEN d.won IS NULL THEN 1 END) AS open_count, COALESCE(SUM(CASE WHEN d.won IS NULL THEN d.value END), 0) AS open_value, COUNT(CASE WHEN d.won IS NOT NULL THEN 1 END) AS closed_count, COALESCE(SUM(CASE WHEN d.won IS NOT NULL THEN (CASE WHEN d.won THEN d.actual_value ELSE d.value END) END), 0) AS closed_value FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
GROUP BY d.stage_id, d.pipeline_id

SELECT COALESCE(SUM(CASE WHEN d.won = TRUE
           AND d.closed_at >= #{startUtc}
           AND d.closed_at < #{endUtc} THEN d.actual_value END), 0) AS won_revenue,
       COALESCE(SUM(CASE WHEN d.created_at >= #{startUtc}
           AND d.created_at < #{endUtc} THEN d.value END), 0) AS new_pipeline,
       COUNT(CASE WHEN d.created_at >= #{startUtc}
           AND d.created_at < #{endUtc} THEN 1 END) AS new_pipeline_count,
       COUNT(CASE WHEN d.won = TRUE
           AND d.closed_at >= #{startUtc}
           AND d.closed_at < #{endUtc} THEN 1 END) AS won_count,
       COUNT(CASE WHEN d.won = FALSE
           AND d.closed_at >= #{startUtc}
           AND d.closed_at < #{endUtc} THEN 1 END) AS lost_count,
       COALESCE(SUM(CASE WHEN d.won = FALSE
           AND d.closed_at >= #{startUtc}
           AND d.closed_at < #{endUtc} THEN d.value END), 0) AS lost_value,
       COALESCE(AVG(CASE WHEN d.won = TRUE
           AND d.closed_at >= #{startUtc}
           AND d.closed_at < #{endUtc}
           AND d.closed_at >= d.created_at
           THEN DATEDIFF(d.closed_at, d.created_at) END), 0) AS avg_cycle_days
FROM deal d
WHERE d.workspace_id = #{workspaceId}


  AND d.currency = #{currency}

SELECT 11 - LEAST(11, GREATEST(0, FLOOR(DATEDIFF(NOW(), d.closed_at) / #{span}))) AS bucket_index, COALESCE(SUM(CASE WHEN d.won = TRUE THEN d.actual_value END), 0) AS won_value, COUNT(CASE WHEN d.won = TRUE THEN 1 END) AS won_count, COUNT(CASE WHEN d.won = FALSE THEN 1 END) AS lost_count, COALESCE(AVG(CASE WHEN d.won = TRUE AND d.closed_at >= d.created_at THEN DATEDIFF(d.closed_at, d.created_at) END), 0) AS avg_cycle_days FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.won IS NOT NULL AND d.closed_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND d.closed_at <= NOW() GROUP BY bucket_index ORDER BY bucket_index

SELECT 11 - LEAST(11, GREATEST(0, FLOOR(DATEDIFF(NOW(), d.created_at) / #{span}))) AS bucket_index, COALESCE(SUM(d.value), 0) AS value FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND d.created_at <= NOW() GROUP BY bucket_index ORDER BY bucket_index

SELECT boundary.bucket_index, COALESCE(SUM(CASE WHEN d.won = TRUE THEN d.actual_value END), 0) AS won_value, COUNT(CASE WHEN d.won = TRUE THEN 1 END) AS won_count, COUNT(CASE WHEN d.won = FALSE THEN 1 END) AS lost_count, COALESCE(AVG(CASE WHEN d.won = TRUE AND d.closed_at >= d.created_at THEN DATEDIFF(d.closed_at, d.created_at) END), 0) AS avg_cycle_days FROM () boundary JOIN deal d FORCE INDEX FOR JOIN (idx_deal_workspace_closed_at) ON d.workspace_id = #{workspaceId} AND d.closed_at >= boundary.start_utc AND d.closed_at < boundary.end_utc WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.won IS NOT NULL AND d.closed_at >= #{startUtc} AND d.closed_at < #{endUtc} GROUP BY boundary.bucket_index ORDER BY boundary.bucket_index

SELECT boundary.bucket_index,
       COALESCE(SUM(d.value), 0) AS value
FROM () boundary
JOIN deal d
  ON d.workspace_id = #{workspaceId}
  AND d.created_at >= boundary.start_utc
  AND d.created_at < boundary.end_utc
WHERE d.workspace_id = #{workspaceId}


  AND d.currency = #{currency}

  AND d.created_at >= #{startUtc}
  AND d.created_at < #{endUtc}
GROUP BY boundary.bucket_index
ORDER BY boundary.bucket_index

SELECT d.pipeline_id AS pipeline_id, COALESCE(SUM(CASE WHEN d.won = TRUE AND d.closed_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND d.closed_at <= NOW() THEN d.actual_value END), 0) AS won_value, COALESCE(SUM(CASE WHEN d.won IS NULL THEN d.value END), 0) AS open_value, COUNT(CASE WHEN d.won IS NULL THEN 1 END) AS open_count FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
GROUP BY d.pipeline_id ORDER BY d.pipeline_id

SELECT d.pipeline_id AS pipeline_id, COALESCE(SUM(CASE WHEN d.won = TRUE AND d.closed_at >= #{startUtc} AND d.closed_at < #{endUtc} THEN d.actual_value END), 0) AS won_value, COALESCE(SUM(CASE WHEN d.won IS NULL THEN d.value END), 0) AS open_value, COUNT(CASE WHEN d.won IS NULL THEN 1 END) AS open_count FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
GROUP BY d.pipeline_id ORDER BY d.pipeline_id

SELECT boundary.bucket_index,
       COALESCE(SUM(d.actual_value), 0) AS total
FROM () boundary
JOIN deal d FORCE INDEX FOR JOIN (idx_deal_workspace_closed_at)
  ON d.workspace_id = #{workspaceId}
  AND d.closed_at >= boundary.start_utc
  AND d.closed_at < boundary.end_utc
WHERE d.workspace_id = #{workspaceId}


  AND d.currency = #{currency}

  AND d.closed_at >= #{startUtc}
  AND d.closed_at < #{endUtc}
  AND (d.won = FALSE OR d.expected_close_date IS NULL)
  AND d.actual_value != 0
GROUP BY boundary.bucket_index
ORDER BY boundary.bucket_index

SELECT boundary.bucket_index,
       COALESCE(SUM(d.actual_value), 0) AS total
FROM () boundary
JOIN deal d
  ON d.workspace_id = #{workspaceId}
  AND d.expected_close_date >= boundary.start_date
  AND d.expected_close_date < boundary.end_date
WHERE d.workspace_id = #{workspaceId}


  AND d.currency = #{currency}

  AND d.closed_at IS NOT NULL
  AND d.won = TRUE
  AND d.expected_close_date >= #{startDate}
  AND d.expected_close_date < #{endDate}
GROUP BY boundary.bucket_index
ORDER BY boundary.bucket_index

SELECT boundary.bucket_index,
       COALESCE(SUM(d.value), 0) AS total
FROM () boundary
JOIN deal d
  ON d.workspace_id = #{workspaceId}
  AND d.expected_close_date >= boundary.start_date
  AND d.expected_close_date < boundary.end_date
WHERE d.workspace_id = #{workspaceId}


  AND d.currency = #{currency}

  AND d.expected_close_date >= #{startDate}
  AND d.expected_close_date < #{endDate}
GROUP BY boundary.bucket_index
ORDER BY boundary.bucket_index

SELECT d.stage_id AS stage_id, COUNT(CASE WHEN DATEDIFF(NOW(), d.updated_at) <= 7 THEN 1 END) AS fresh, COUNT(CASE WHEN DATEDIFF(NOW(), d.updated_at) > 7 AND DATEDIFF(NOW(), d.updated_at) <= 30 THEN 1 END) AS active, COUNT(CASE WHEN DATEDIFF(NOW(), d.updated_at) > 30 AND DATEDIFF(NOW(), d.updated_at) <= 60 THEN 1 END) AS aging, COUNT(CASE WHEN DATEDIFF(NOW(), d.updated_at) > 60 THEN 1 END) AS stalled FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.won IS NULL AND d.stage_id IS NOT NULL GROUP BY d.stage_id ORDER BY d.stage_id

SELECT 
FROM deal d
WHERE d.workspace_id = #{workspaceId}
  AND d.won IS NULL
  AND d.closed_at IS NULL
  AND d.expected_close_date >= #{today}
  AND d.expected_close_date <= DATE_ADD(#{today}, INTERVAL #{days} DAY)
ORDER BY d.expected_close_date, d.id
LIMIT #{limit}

SELECT FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.won IS NULL ORDER BY d.value DESC, d.id ASC LIMIT 3

SELECT FROM deal d WHERE d.workspace_id = #{workspaceId}
AND d.currency = #{currency}
AND d.won = TRUE ORDER BY d.actual_value DESC, d.id ASC LIMIT 3

SELECT 
FROM deal d
WHERE d.workspace_id = #{workspaceId}
  AND d.pipeline_id = #{pipelineId}
ORDER BY d.stage_id, d.position, d.id

SELECT 
FROM deal
WHERE workspace_id = #{workspaceId} AND company_id = #{companyId}
ORDER BY stage_id, position, id
LIMIT #{limit}

SELECT 
FROM deal
WHERE workspace_id = #{workspaceId}
  AND company_id = #{companyId}
  AND id <> #{excludeDealId}
ORDER BY (won IS NULL), COALESCE(closed_at, expected_close_date) DESC, id
LIMIT #{limit}

SELECT 
FROM deal
WHERE workspace_id = #{workspaceId} AND id = #{id}

SELECT EXISTS(
  SELECT 1 FROM deal WHERE workspace_id = #{workspaceId} AND id = #{id}
)

SELECT  FROM deal
WHERE workspace_id = #{workspaceId} AND id IN
#{id}

SELECT  FROM deal
WHERE workspace_id = #{workspaceId}
  AND company_id IN
  #{id}
ORDER BY id

SELECT id FROM deal
WHERE workspace_id = #{workspaceId} AND stage_id = #{stageId}
ORDER BY position, id

