FROM deal d
WHERE d.workspace_id = #{workspaceId} AND d.id = #{dealId}

INSERT IGNORE INTO deal_tag (deal_id, tag_id)
SELECT d.id, t.id
FROM deal d
JOIN tag t ON t.id IN

  #{tagId}

WHERE d.workspace_id = #{workspaceId} AND d.id = #{dealId} AND t.workspace_id = #{workspaceId}

INSERT INTO deal_person (deal_id, person_id, role)
SELECT d.id, p.id, #{role}
FROM deal d
JOIN person p ON p.id = #{personId} AND 
WHERE d.workspace_id = #{workspaceId} AND d.id = #{dealId}
ON DUPLICATE KEY UPDATE role = #{role}

