UPDATE deal_person dp
JOIN deal d ON d.id = dp.deal_id
JOIN person p ON p.id = dp.person_id AND 
SET dp.role = #{role}
WHERE d.workspace_id = #{workspaceId}
  AND dp.deal_id = #{dealId}
  AND dp.person_id = #{personId}

